def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        safe = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 2:
            safe = DAILY_SALARY * 0.75
        return float(min(budget, safe))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    strongest_id = None
    strongest_score = -1.0
    strongest_prev_bid = 0.0
    max_prev_bid = 0.0
    active_pressure = 0.0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid', 0.0)
        if prev_bid is None:
            prev_bid = 0.0
        if prev_bid > max_prev_bid:
            max_prev_bid = prev_bid

        score = opp.get('budget', 0.0) + 8.0 * opp.get('hp', 0) - 12.0 * opp.get('no_water_days', 0)
        if score > strongest_score:
            strongest_score = score
            strongest_id = agent_id
            strongest_prev_bid = prev_bid

        if opp.get('budget', 0.0) > DAILY_SALARY * 2 and opp.get('hp', 0) > 2:
            active_pressure += prev_bid

    emergency = hp <= 2 or no_water >= 2
    strained = hp <= 4 or no_water >= 1

    if emergency:
        bid = DAILY_SALARY * (0.92 + 0.06 * scarcity)
    elif strained:
        bid = DAILY_SALARY * (0.62 + 0.18 * scarcity)
    else:
        bid = DAILY_SALARY * (0.34 + 0.16 * scarcity)

    if strongest_id == 'Cindy':
        if scarcity >= 0.6 and not emergency:
            target = strongest_prev_bid + 2.0
            cap = DAILY_SALARY * 0.88
            bid = max(bid, min(target, cap))
        elif strongest_prev_bid >= DAILY_SALARY * 1.5 and hp > 4 and no_water == 0:
            bid = min(bid, DAILY_SALARY * 0.4)

    if max_prev_bid <= 1.0 and hp > 4 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.28)

    if active_pressure > 0 and scarcity >= 0.7 and not emergency:
        bid = max(bid, min(DAILY_SALARY * 0.82, max_prev_bid + 1.5))

    reserve_floor = 0.0
    if day <= 7 and not emergency:
        reserve_floor = DAILY_SALARY * 1.2
    if budget <= reserve_floor:
        bid = min(bid, max(0.0, budget - reserve_floor * 0.25))

    if emergency:
        bid = max(bid, DAILY_SALARY * 0.8)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    # day_context: {'supply','day'}
    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        # conserve budget
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate: if someone bid extremely high yesterday, they likely expect scarcity
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely available relative to our need.
    # supply is total available; if supply is just enough, competition rises.
    # Use int indices safely; no lists are indexed here but keep robust.
    supply_units = supply / float(WATER_REQ) if WATER_REQ > 0 else 0.0

    # Baseline bid: aim to be competitive but not max.
    # Medium scenario supply 15-25 => supply_units ~1.67-2.78
    # If supply_units is low, bid higher.
    if supply_units < 2.0:
        baseline = DAILY_SALARY * 0.7
    else:
        baseline = DAILY_SALARY * 0.55

    # Escalate based on our health and no-water streak.
    if hp <= 2.0:
        baseline = DAILY_SALARY * 0.9
    elif hp <= 4.0 or no_water_days >= 2:
        baseline = max(baseline, DAILY_SALARY * 0.75)

    # Reaction to opponent aggression yesterday
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Someone paid near capacity; match closer.
        baseline = max(baseline, DAILY_SALARY * 0.8)
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        baseline = max(baseline, DAILY_SALARY * 0.65)

    # Convert to final bid, capped by budget. Also keep within a reasonable fraction of daily salary.
    # If budget is tiny, don't exceed it.
    bid_cap = min(budget, DAILY_SALARY * 0.95)
    bid = min(bid_cap, baseline)

    # If we are still healthy and budget allows, slightly underbid to save funds.
    if hp >= 6.0 and no_water_days == 0:
        bid = min(bid_cap, bid * 0.9)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13
    EPISODE_DAYS = 10

    alive_opponents = [agent_id for agent_id, opp_data in opponents_status.items() if opp_data['alive']]

    remaining_days = EPISODE_DAYS - day_context['day']

    bid = DAILY_SALARY * 0.5 

    if not alive_opponents:
        if my_status['hp'] > 5:
            return min(my_status['budget'], DAILY_SALARY * 0.3)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.6)

    yesterday_bids = []
    alex_yesterday_bid = 0.0

    for agent_id in alive_opponents:
        opp = opponents_status[agent_id]
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
            if agent_id == 'Alex':
                alex_yesterday_bid = prev['bid']

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        bid = max(bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.75)

    num_possible_winners = int(day_context['supply'] // WATER_REQ)
    num_alive_competitors = len(alive_opponents) + 1

    if num_alive_competitors > num_possible_winners:
        if highest_prev_bid > 0:
            bid = max(bid, highest_prev_bid + 5.0)
        else:
            bid = max(bid, DAILY_SALARY * 0.6)

        if 'Alex' in alive_opponents:
            if day_context['supply'] <= WATER_REQ * 2:
                bid = max(bid, DAILY_SALARY * 0.9)
            else:
                bid = max(bid, DAILY_SALARY * 0.75)

            if alex_yesterday_bid > 0:
                bid = max(bid, alex_yesterday_bid + 2.0)
    else:
        bid = min(bid, DAILY_SALARY * 0.6)
        if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 0.5:
            bid = min(bid, highest_prev_bid + 1.0)

    if remaining_days <= 2:
        bid = max(bid, DAILY_SALARY * 0.98)
    elif remaining_days <= 4:
        bid = max(bid, DAILY_SALARY * 0.85)

    bid = min(bid, my_status['budget'])

    if bid == 0.0 and my_status['budget'] > 0 and my_status['hp'] < 10:
        bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    bid = max(0.0, bid)

    return bid
